insert into faqs (id, category, question, answer, sort_order, is_active, created_at)
values
  ('8965b014-d535-4b80-926a-584feedc27f4', $faq$Decant гэж юу вэ$faq$, $faq$Decant гэж юу вэ?$faq$, $faq$Үйлдвэрийн бүтэн савнаас үнэртнийг жижиг саванд хувааж савласныг decant гэнэ. Агуулга нь яг тэр ус, зөвхөн хэмжээ нь бага.$faq$, 0, true, '2026-09-21T04:33:12.622Z'),
  ('825ec9af-ae8b-4fe6-915e-0c137ccf0654', $faq$Decant гэж юу вэ$faq$, $faq$Бараа жинхэнэ гэдэгт итгэж болох уу?$faq$, $faq$Тийм. Бид зөвхөн албан ёсны эх сурвалжаас авсан бүтэн савнаас хувааж савладаг.$faq$, 1, true, '2026-09-21T04:33:12.622Z'),
  ('0c67da68-3d18-4b95-bf59-2e4b05fe8bac', $faq$Decant гэж юу вэ$faq$, $faq$Яагаад decant авах нь ашигтай вэ?$faq$, $faq$Бүтэн сав авахаасаа өмнө өөрийн арьсан дээрээ туршиж үзэх боломжтой. Нэг бүтэн усны үнээр хэд хэдэн үнэр туршиж, өөрт тохирохыг нь олно.$faq$, 2, true, '2026-09-21T04:33:12.622Z'),
  ('0543a017-1ce3-4d5d-822e-02a3536947b8', $faq$Decant гэж юу вэ$faq$, $faq$Хэрхэн хадгалах вэ?$faq$, $faq$Нар тусахгүй, халуун биш газар, тагийг нь сайн таглаж хадгална. Ингэвэл үнэр удаан хугацаанд чанараа алдахгүй.$faq$, 3, true, '2026-09-21T04:33:12.622Z'),
  ('8ea12afd-ad65-49e8-b7cf-032bee4cfc60', $faq$Decant гэж юу вэ$faq$, $faq$EDP, EDT, Extrait гэдэг нь юу гэсэн үг вэ?$faq$, $faq$Үнэрийн тосны агууламжийн зэрэг юм. Агууламж өндөр байх тусам үнэр тогтвортой, арьсан дээр удаан барина.$faq$, 4, true, '2026-09-21T04:33:12.622Z'),
  ('5595224e-6629-48c0-baa7-fac3095bb182', $faq$Хэмжээ ба багц$faq$, $faq$Ямар хэмжээ байдаг вэ?$faq$, $faq$2мл, 5мл, 10мл, 20мл. Ус бүр дээр аль хэмжээ нь бэлэн байгааг барааны хуудаснаас харна.$faq$, 5, true, '2026-09-21T04:33:12.622Z'),
  ('c4490a97-f088-476d-8e6d-5915063b4561', $faq$Хэмжээ ба багц$faq$, $faq$2, 5, 10, 20мл юугаараа ялгаатай вэ?$faq$, $faq$<p>Зөвхөн хэмжээний ялгаа. Найрлага ижил. Бага хэмжээ нь туршихад, их хэмжээ нь тогтмол хэрэглэхэд тохиромжтой.</p>$faq$, 6, true, '2026-09-21T04:23:07.710Z'),
  ('d7675c2e-1d6d-4e91-9959-19f3799ca3cf', $faq$Хэмжээ ба багц$faq$, $faq$Багц гэж юу вэ?$faq$, $faq$Хэд хэдэн үнэрийг нэг дор авах сонголт. Бидний бэлдсэн бэлэн багцаас сонгох, эсвэл дуртай усаа сонгон өөрийн багцаа угсарч болно.$faq$, 7, true, '2026-09-21T04:33:12.622Z'),
  ('d8132c7c-9c97-4991-8f6c-d06a3224b0c1', $faq$Хэмжээ ба багц$faq$, $faq$Багц дотор өөр өөр хэмжээ хольж болох уу?$faq$, $faq$Өөрөө угсрах багц нэг хэмжээн дээр угсрагдана. Өөр хэмжээ нэмж авах бол тусад нь сагсандаа нэмээрэй.$faq$, 8, true, '2026-09-21T04:33:12.622Z'),
  ('2f3cebe4-14fe-401d-bfea-968330ae8faa', $faq$Захиалга ба төлбөр$faq$, $faq$Хэрхэн төлбөр төлөх вэ?$faq$, $faq$Захиалгаа баталгаажуулмагц QPay-ийн QR код гарч ирнэ. Банкны аппаараа уншуулж төлөхөд төлбөр автоматаар баталгаажна.$faq$, 9, true, '2026-09-21T04:33:12.622Z'),
  ('07b2bacd-1ac0-434f-a594-c4ff2d312982', $faq$Захиалга ба төлбөр$faq$, $faq$Төлбөрөө хэдэн минутад багтаан хийх вэ?$faq$, $faq$35 минутын дотор. Тэр хугацаанд төлөгдөөгүй захиалга автоматаар цуцлагдаж, бараа нь дахин худалдаанд гарна.$faq$, 10, true, '2026-09-21T04:33:12.622Z'),
  ('3a1198d2-54e5-4df0-8100-4cbaf3023192', $faq$Захиалга ба төлбөр$faq$, $faq$Бүртгэлгүйгээр захиалж болох уу?$faq$, $faq$Болно. Харин бүртгэлтэй бол V point хуримтлуулж, захиалгынхаа түүхийг нэг дороос харах боломжтой.$faq$, 11, true, '2026-09-21T04:33:12.622Z'),
  ('af05dfe1-db05-4031-81c2-9b07699a8aa0', $faq$Захиалга ба төлбөр$faq$, $faq$Захиалгаа хаанаас хянах вэ?$faq$, $faq$Нэвтэрсэн бол «Миний захиалга» хэсгээс харна. Зочноор захиалсан бол захиалгынхаа дугаараар хайж төлвөө шалгана.$faq$, 12, true, '2026-09-21T04:33:12.622Z'),
  ('60c0827a-d00a-4697-85c9-893ce3b97ef0', $faq$Захиалга ба төлбөр$faq$, $faq$Нэг захиалгад хэдэн купон ашиглах вэ?$faq$, $faq$Нэг захиалгад нэг купон ашиглана. Хэд хэдэн купонтой бол хамгийн ашигтайг нь сонгоорой.$faq$, 13, true, '2026-09-21T04:33:12.622Z'),
  ('ea714675-dc39-40c9-be81-c984b673dc77', $faq$Захиалга ба төлбөр$faq$, $faq$Оноогоор төлбөрөө хөнгөлж болох уу?$faq$, $faq$Болно. Хуримтлуулсан V point-оо захиалга баталгаажуулах үедээ хасалт болгон ашиглана.$faq$, 14, true, '2026-09-21T04:33:12.622Z'),
  ('04cb3c05-45e2-4d58-bb3b-8f1342e2f638', $faq$Хүргэлт$faq$, $faq$Хэзээ хүргэгдэх вэ?$faq$, $faq$Захиалга өгөхдөө хүргүүлэх өдрөө өөрөө сонгоно. Хамгийн эрт нь маргааш, хамгийн хол нь 14 хоногийн дараа.$faq$, 15, true, '2026-09-21T04:33:12.622Z'),
  ('63f07dfa-3a6f-40cb-88b1-a7bfa4077524', $faq$Хүргэлт$faq$, $faq$Өдрийн хэдэн цагт хүргэдэг вэ?$faq$, $faq$Сонгосон өдрийн чинь 11:00 цагт хүргэлт гарч, оройн 23:00 цаг гэхэд хүргэж дуусна.$faq$, 16, true, '2026-09-21T04:33:12.622Z'),
  ('92d88023-5d86-437a-b54d-05c68daf6f55', $faq$Хүргэлт$faq$, $faq$Амралтын өдөр хүргэдэг үү?$faq$, $faq$Тийм. Амралтын өдөр ажлын өдөртэй ижил хүргэнэ.$faq$, 17, true, '2026-09-21T04:33:12.622Z'),
  ('bd8c1b95-2ddb-40b1-b707-b5b14ec6322b', $faq$Хүргэлт$faq$, $faq$Хүргэлтийн төлбөр хэд вэ?$faq$, $faq$Хаягийн бүсээс хамаарч 7,000₮-өөс эхэлнэ. Яг ямар дүн болохыг захиалга баталгаажуулах хуудсанд хаягаа сонгоход харуулна.$faq$, 18, true, '2026-09-21T04:33:12.622Z'),
  ('ab3d5506-7133-41cc-9ff8-b467a4935176', $faq$Хүргэлт$faq$, $faq$Орон нутагт хүргэдэг үү?$faq$, $faq$Тийм. Орон нутгийн хаяг сонгосон бол ачаа тээврийн цэгээ заавал бичиж өгнө үү — бид тэр цэг хүртэл нь хүргэнэ.$faq$, 19, true, '2026-09-21T04:33:12.622Z'),
  ('1d0efc05-8842-427e-86d0-b3bcc1ee8b7d', $faq$Хүргэлт$faq$, $faq$Хүргэлтийн хаягаа солих боломжтой юу?$faq$, $faq$Хүргэх өдөр эхлэхээс өмнө захиалгаа цуцлаад шинээр өгөх боломжтой. Яаралтай бол бидэнтэй утсаар холбогдоорой.$faq$, 20, true, '2026-09-21T04:33:12.622Z'),
  ('9dafd3b0-cd0a-4e7b-bbd2-28e445353de5', $faq$Цуцлалт ба буцаалт$faq$, $faq$Захиалгаа цуцлах боломжтой юу?$faq$, $faq$Хүргэх өдөр эхлэх хүртэл, өөрөөр хэлбэл өмнөх өдрийн шөнө дунд хүртэл цуцална. Түүнээс хойш бэлтгэл эхэлсэн тул цуцлах боломжгүй.$faq$, 21, true, '2026-09-21T04:33:12.622Z'),
  ('ffb2e814-f050-4245-a245-fd8b561a2996', $faq$Цуцлалт ба буцаалт$faq$, $faq$Цуцлахад ашигласан оноо, купон яах вэ?$faq$, $faq$Автоматаар буцаж орно. Төлсөн мөнгийг тань бид тантай холбогдож шилжүүлнэ.$faq$, 22, true, '2026-09-21T04:33:12.622Z'),
  ('2d9d62c6-af9e-4175-9481-a39fa3c08291', $faq$Цуцлалт ба буцаалт$faq$, $faq$Задалсан барааг буцаах боломжтой юу?$faq$, $faq$Ариун цэврийн шаардлагаар задалсан decant буцаагддаггүй. Барааны гэмтэл, эндүүрэл гарсан бол бидэнтэй шууд холбогдоорой — бид хамтдаа шийднэ.$faq$, 23, true, '2026-09-21T04:33:12.622Z'),
  ('5202e3e7-1cea-4375-9c97-42404e566b82', $faq$V point ба бэлэг$faq$, $faq$V point хэрхэн цуглах вэ?$faq$, $faq$Төлбөр нь баталгаажсан захиалгын барааны дүнгийн 100₮ тутамд 1 оноо цугларна. 1 оноо нь 1₮ болж дараагийн худалдан авалтаас хасагдана.$faq$, 24, true, '2026-09-21T04:33:12.622Z'),
  ('19a875ec-6525-4b4e-90cb-6beee21554b1', $faq$V point ба бэлэг$faq$, $faq$1мл бэлгийн дээжийг хэрхэн авах вэ?$faq$, $faq$Хөнгөлөлтийн дараах барааны дүн 200,000₮ хүрэх тутамд нэг дээж сонгох эрх нээгдэнэ. Дээжээ захиалга баталгаажуулах хуудсанд сонгоно.$faq$, 25, true, '2026-09-21T04:33:12.622Z');
